impl GetSpan for Expression<'_> {
    fn span(&self) -> Span {
        match self {
            Self::Nil(span)
            | Self::False(span)
            | Self::True(span)
            | Self::VarArg(span)
            | Self::Error(span) => *span,
            Self::Number(literal) | Self::Integer(literal) | Self::StringLiteral(literal) => {
                literal.span()
            }
            Self::FunctionDef(function_def) => function_def.span(),
            Self::Name(name) => name.span(),
            Self::Suffixed(suffixed_expr) => suffixed_expr.span(),
            Self::Parenthesized(parenthesized_expr) => parenthesized_expr.span(),
            Self::TableConstructor(table_constructor) => table_constructor.span(),
            Self::BinaryOp(binary_op) => binary_op.span(),
            Self::UnaryOp(unary_op) => unary_op.span(),
            Self::IfExpression(if_expr) => if_expr.span(),
            Self::InterpolatedString(interpolated_string) => interpolated_string.span(),
            Self::TypeCast(type_cast) => type_cast.span(),
        }
    }
}

impl GetSpan for Var<'_> {
    fn span(&self) -> Span {
        match self {
            Self::Name(name) => name.span(),
            Self::Suffixed(suffixed_expr) => suffixed_expr.span(),
        }
    }
}

impl GetSpan for SuffixedExpression<'_> {
    #[inline]
    fn span(&self) -> Span {
        self.span
    }
}

impl GetSpan for Suffix<'_> {
    fn span(&self) -> Span {
        match self {
            Self::Field(name) => name.span(),
            Self::Index { span, .. } | Self::TypeInstantiation { span, .. } => *span,
            Self::Call(function_args) => function_args.span(),
            Self::MethodCall(method_call) => method_call.span(),
        }
    }
}

impl GetSpan for MethodCall<'_> {
    #[inline]
    fn span(&self) -> Span {
        let mut span = self.name.span().merge(self.args.span());
        if let Some(type_args) = &self.type_args {
            span = span.merge(type_args.span());
        }
        span
    }
}

